class MainActivity : ComponentActivity() {
  private val frameThread = HandlerThread("frames").apply { start() }

  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    setContent { AppTheme { Home() } }

    // API 24+: a full per-frame breakdown, on any device, no tooling attached
    window.addOnFrameMetricsAvailableListener({ _, metrics, _ ->
      val m = FrameMetrics(metrics)          // copy — the instance is reused
      val ms = { id: Int -> m.getMetric(id) / 1_000_000.0 }
      if (ms(FrameMetrics.TOTAL_DURATION) > 8.3) {
        Log.w(
          "frame",
          "total=%.1f measure=%.1f draw=%.1f sync=%.1f issue=%.1f swap=%.1f late=%.1f".format(
            ms(FrameMetrics.TOTAL_DURATION),
            ms(FrameMetrics.LAYOUT_MEASURE_DURATION),
            ms(FrameMetrics.DRAW_DURATION),          // records the display list
            ms(FrameMetrics.SYNC_DURATION),          // hands it to the RenderThread
            ms(FrameMetrics.COMMAND_ISSUE_DURATION), // GPU commands
            ms(FrameMetrics.SWAP_BUFFERS_DURATION),
            ms(FrameMetrics.UNKNOWN_DELAY)           // the frame started late
          )
        )
      }
    }, Handler(frameThread.looper))
  }
}

