// ✅ say out loud what each pool is for
private fun pool(name: String, priority: Int, size: Int): ExecutorService =
  Executors.newFixedThreadPool(size) { runnable ->
    Thread({
      Process.setThreadPriority(priority)
      runnable.run()
    }, name)
  }

private val visible = pool("decode-visible", Process.THREAD_PRIORITY_DEFAULT, 2)
private val prefetch = pool("decode-prefetch", Process.THREAD_PRIORITY_BACKGROUND, 2)

// Coroutines: dispatcher threads are pooled and reused, so a priority you set
// sticks to the thread. Demote for work nobody is waiting on, then restore.
suspend fun warmCache() = withContext(Dispatchers.IO) {
  Process.setThreadPriority(Process.THREAD_PRIORITY_BACKGROUND)
  try {
    prefetchAll()
  } finally {
    Process.setThreadPriority(Process.THREAD_PRIORITY_DEFAULT)
  }
}

